    input  logic x,
    output logic z
);

    logic q_xor, q_and, q_or;
    logic d_xor, d_and, d_or;

    // Gate definitions
    assign d_xor = x ^ q_xor;
    assign d_and = x & ~q_and;
    assign d_or  = x | ~q_or;

    // D flip-flops with initial zero state for simulation
    initial begin
        q_xor = 1'b0;
        q_and = 1'b0;
        q_or  = 1'b0;
    end

    always_ff @(posedge clk) begin
        q_xor <= d_xor;
        q_and <= d_and;
        q_or  <= d_or;
    end

    // Three-input NOR gate for output z
    assign z = ~(q_xor | q_and | q_or);

endmodule

